use biome_console::markup;
use biome_css_syntax::{
    AnyCssSelector, CssNestedQualifiedRule, CssQualifiedRule, CssSyntaxKind,
};
use biome_rowan::{AstNode, TextRange, declare_node_union};
use biome_rule_options::no_excessive_selector_classes::NoExcessiveSelectorClassesOptions;

declare_lint_rule! {
    /// Disallow selectors with too many class selectors.
    ///
    /// Selectors that chain together many class selectors are harder to read,
    /// harder to override, and harder to reuse. This rule flags any individual
    /// selector whose total number of class selectors exceeds the configured
    /// maximum.
    ///
    /// Class selectors are counted across the whole selector, including those
    /// nested inside pseudo-class function arguments such as `:not()`, `:is()`,
    /// `:has()`, and `:nth-child(... of ...)`. Each selector in a comma-separated
    /// list is evaluated independently, and nested selectors are evaluated
    /// independently from their parent.
    ///
    /// When the `maxClasses` option is not configured, the rule reports nothing.
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```css,expect_diagnostic,use_options
    /// .a.b {}
    /// ```
    ///
    /// ### Valid
    ///
    /// ```css,use_options
    /// .a {}
    /// ```
    ///
    /// ## Options
    ///
    /// ### `maxClasses`
    ///
    /// The maximum number of class selectors allowed in a single selector.
    ///
    /// ```json,options
    /// {
    ///     "options": {
    ///        "maxClasses": 1
    ///     }
    /// }
    /// ```
    ///
    pub NoExcessiveSelectorClasses {
        version: "next",
        name: "noExcessiveSelectorClasses",
        language: "css",
        recommended: false,
    }
}

declare_node_union! {
    pub AnyCssQualifiedRuleLike = CssQualifiedRule | CssNestedQualifiedRule
}

pub struct RuleState {
    /// The range of the offending selector.
    range: TextRange,
    /// The number of class selectors found in the selector.
    found: usize,
}

impl Rule for NoExcessiveSelectorClasses {
    type Query = Ast<AnyCssQualifiedRuleLike>;
    type State = RuleState;
    type Signals = Box<[Self::State]>;
    type Options = NoExcessiveSelectorClassesOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let Some(max_classes) = ctx.options().max_classes else {
            return Box::new([]);
        };
        let max_classes = usize::from(max_classes);

        let node = ctx.query();

        node.selectors()
            .filter_map(|selector| {
                // SCSS interpolation makes the class count non-deterministic, so
                // selectors containing interpolation are never flagged.
                if selector_has_interpolation(&selector) {
                    return None;
                }

                let found = count_class_selectors(&selector);
                if found > max_classes {
                    Some(RuleState {
                        range: selector.range(),
                        found,
                    })
                } else {
                    None
                }
            })
            .collect()
    }

    fn diagnostic(ctx: &RuleContext<Self>, state: &Self::State) -> Option<RuleDiagnostic> {
        let max_classes = usize::from(ctx.options().max_classes?);
        let found = state.found;

        let message = if max_classes == 1 {
            markup! {
                "Expected this selector to have no more than "{max_classes}" class selector, but found "{found}"."
            }
            .to_owned()
        } else {
            markup! {
                "Expected this selector to have no more than "{max_classes}" class selectors, but found "{found}"."
            }
            .to_owned()
        };

        Some(
            RuleDiagnostic::new(rule_category!(), state.range, message)
                .note(markup! {
                    "Selectors with too many chained classes are harder to read, override, and reuse."
                })
                .note(markup! {
                    "Reduce the number of class selectors in this selector, or split it into simpler selectors."
                }),
        )
    }
}

impl AnyCssQualifiedRuleLike {
    /// Returns all the top-level selectors of the rule's prelude.
    fn selectors(&self) -> Box<[AnyCssSelector]> {
        match self {
            Self::CssQualifiedRule(rule) => {
                rule.prelude().into_iter().flatten().collect()
            }
            Self::CssNestedQualifiedRule(rule) => rule
                .prelude()
                .into_iter()
                .flatten()
                .filter_map(|relative| relative.selector().ok())
                .collect(),
        }
    }
}

/// Counts every class selector contained in the given selector, including those
/// nested inside pseudo-class function arguments.
fn count_class_selectors(selector: &AnyCssSelector) -> usize {
    selector
        .syntax()
        .descendants()
        .filter(|node| node.kind() == CssSyntaxKind::CSS_CLASS_SELECTOR)
        .count()
}

/// Returns `true` if the selector contains any SCSS interpolation.
fn selector_has_interpolation(selector: &AnyCssSelector) -> bool {
    selector.syntax().descendants().any(|node| {
        matches!(
            node.kind(),
            CssSyntaxKind::SCSS_INTERPOLATION | CssSyntaxKind::SCSS_INTERPOLATED_IDENTIFIER
        )
    })
