use biome_analyze::{
    AnalysisFilter, AnalyzerConfiguration, AnalyzerOptions, AnalyzerRules, ControlFlow, Never,
    RuleFilter, RuleKey,
};
use biome_css_analyze::{CssAnalyzerServices, analyze};
use biome_css_parser::{CssParserOptions, parse_css};
use biome_css_syntax::CssFileSource;
use biome_rule_options::no_excessive_selector_classes::NoExcessiveSelectorClassesOptions;
use std::slice;

fn run(source: &str, max_classes: Option<u16>, scss: bool) -> Vec<String> {
    let file_source = if scss {
        CssFileSource::scss()
    } else {
        CssFileSource::css()
    };
    let parsed = parse_css(source, file_source, CssParserOptions::default());

    let mut rules = AnalyzerRules::default();
    rules.push_rule(
        RuleKey::new("nursery", "noExcessiveSelectorClasses"),
        RuleOptions::new(NoExcessiveSelectorClassesOptions { max_classes }, None),
    );
    let options = AnalyzerOptions::default()
        .with_configuration(AnalyzerConfiguration::default().with_rules(rules));

    let rule_filter = RuleFilter::Rule("nursery", "noExcessiveSelectorClasses");
    let semantic_model = biome_css_semantic::semantic_model(&parsed.tree());
    let services = CssAnalyzerServices::default()
        .with_file_source(file_source)
        .with_semantic_model(&semantic_model);

    let mut messages = Vec::new();
    analyze(
        &parsed.tree(),
        AnalysisFilter {
            enabled_rules: Some(slice::from_ref(&rule_filter)),
            ..AnalysisFilter::default()
        },
        &options,
        services,
        &[],
        |signal| {
            if let Some(diag) = signal.diagnostic() {
                let span = diag.location().span;
                messages.push(format!("{:?} @ {:?}", diag.message.to_string(), span));
            }
            ControlFlow::<Never>::Continue(())
        },
    );
    messages
}

fn check(label: &str, source: &str, max_classes: Option<u16>, scss: bool, expected: usize) {
    let msgs = run(source, max_classes, scss);
    let status = if msgs.len() == expected { "OK " } else { "FAIL" };
    println!(
        "[{status}] {label}: expected {expected} diag(s), got {} for {:?} (max={:?})",
        msgs.len(),
        source,
        max_classes
    );
    for m in &msgs {
        println!("        - {m}");
    }
}

fn main() {
    // No option configured => never fires.
    check("none-config", ".a.b.c.d {}", None, false, 0);
    // max=1 => 2+ classes fire.
    check("max1-two", ".a.b {}", Some(1), false, 1);
    check("max1-one", ".a {}", Some(1), false, 0);
    check("max1-descendant", ".a .b {}", Some(1), false, 1);
    check("max1-with-element", "div.a .b {}", Some(1), false, 1);
    // max=0 => 1+ classes fire.
    check("max0-one", ".a {}", Some(0), false, 1);
    check("max0-none", "div {}", Some(0), false, 0);
    // max=2 => 3+ classes fire.
    check("max2-three", ".a.b.c {}", Some(2), false, 1);
    check("max2-two", ".a.b {}", Some(2), false, 0);
    // pseudo-class function args counted.
    check("not-inner", ".a.b:not(.c.d) {}", Some(1), false, 1); // 4 classes
    check("is-inner", ":is(.a, .b) {}", Some(1), false, 1);
    check("nth-of", ".a:nth-child(2n of .b) {}", Some(1), false, 1);
    // comma list independent.
    check("comma-list", ".a.b, .c {}", Some(1), false, 1); // only first fires
    check("comma-both", ".a.b, .c.d {}", Some(1), false, 2);
    // nested independent from parent.
    check("nested-indep", ".a.b { & .c {} }", Some(1), false, 1); // only parent .a.b fires
    check("nested-fires", ".a { &.b.c {} }", Some(1), false, 1); // only nested fires
    // scss interpolation not flagged.
    check("scss-interp", ".a.#{$x} {}", Some(1), true, 0);
    check("scss-interp-many", ".a.b.#{$x} {}", Some(0), true, 0);
}
